/* The synchronous std.process operations and those of std.signal, which report
   std.process::process_error (Library R-SLIB-SIGNAL-0001, R-SLIB-SIGNAL-0003). */
static bool r_c17_process_simple_operation(RStandardCallOperation operation) {
    return ((operation >= R_STANDARD_CALL_PROCESS_COMMAND_CREATE) &&
            (operation <= R_STANDARD_CALL_PROCESS_ABORT)) ||
           (operation == R_STANDARD_CALL_SIGNAL_LISTEN) ||
           (operation == R_STANDARD_CALL_SIGNAL_RAISE);
}

/* The operations of std.signal, whose header is r_std_signal.h. */
static bool r_c17_standard_operation_is_signal(RStandardCallOperation operation) {
    return (operation == R_STANDARD_CALL_SIGNAL_LISTEN) ||
           (operation == R_STANDARD_CALL_SIGNAL_RAISE) ||
           (operation == R_STANDARD_CALL_SIGNAL_NEXT);
}

/* The asynchronous std.process operations and std.signal::next (R-SLIB-SIGNAL-0002). */
static bool r_c17_process_async_operation(RStandardCallOperation operation) {
    return ((operation >= R_STANDARD_CALL_PROCESS_SPAWN) &&
            (operation <= R_STANDARD_CALL_PROCESS_TERMINATE)) ||
           (operation == R_STANDARD_CALL_SIGNAL_NEXT);
}
