static void *r_c17_allocate(RC17Emitter *emitter, size_t size) {
    void *result;

    if ((size == 0U) || (emitter->status != R_FRONTEND_OK)) {
        return NULL;
    }
    result =
        emitter->frontend->options.allocate(emitter->frontend->options.allocator_user_data, size);
    if (result == NULL) {
        emitter->status = R_FRONTEND_OUT_OF_MEMORY;
    }
    return result;
}

static void r_c17_free(RC17Emitter *emitter, void *pointer) {
    if (pointer != NULL) {
        emitter->frontend->options.free(emitter->frontend->options.allocator_user_data, pointer);
    }
}

static bool r_c17_prepared_place_push(RC17Emitter *emitter,
                                      RC17PreparedPlace *prepared,
                                      const RHirNode *place,
                                      uint32_t temporary) {
    if (prepared->index_count == prepared->index_capacity) {
        const size_t capacity = prepared->index_capacity == 0U ? 4U : prepared->index_capacity * 2U;
        RC17PreparedIndex *replacement;

        if ((capacity < prepared->index_capacity) || (capacity > SIZE_MAX / sizeof(*replacement))) {
            return r_c17_fail(emitter, R_FRONTEND_LIMIT_EXCEEDED);
        }
        replacement = r_c17_allocate(emitter, capacity * sizeof(*replacement));
        if (replacement == NULL) {
            return false;
        }
        if (prepared->index_count != 0U) {
            (void)memcpy(
                replacement, prepared->indices, prepared->index_count * sizeof(*replacement));
        }
        r_c17_free(emitter, prepared->indices);
        prepared->indices = replacement;
        prepared->index_capacity = capacity;
    }
    prepared->indices[prepared->index_count].place = place;
    prepared->indices[prepared->index_count].temporary = temporary;
    prepared->index_count += 1U;
    return true;
}

static void r_c17_prepared_place_destroy(RC17Emitter *emitter, RC17PreparedPlace *prepared) {
    r_c17_free(emitter, prepared->indices);
    (void)memset(prepared, 0, sizeof(*prepared));
}

static bool r_c17_push_effect_handler(
    RC17Emitter *emitter, RTypeId error_type, uint32_t label, size_t finally_count, size_t group) {
    RC17EffectHandler *replacement;
    size_t capacity;

    if (emitter->effect_handler_count == emitter->effect_handler_capacity) {
        capacity =
            emitter->effect_handler_capacity == 0U ? 8U : emitter->effect_handler_capacity * 2U;
        if ((capacity < emitter->effect_handler_capacity) ||
            (capacity > (SIZE_MAX / sizeof(*replacement)))) {
            return r_c17_fail(emitter, R_FRONTEND_LIMIT_EXCEEDED);
        }
        replacement = r_c17_allocate(emitter, capacity * sizeof(*replacement));
        if (replacement == NULL) {
            return false;
        }
        if (emitter->effect_handler_count != 0U) {
            (void)memcpy(replacement,
                         emitter->effect_handlers,
                         emitter->effect_handler_count * sizeof(*replacement));
        }
        r_c17_free(emitter, emitter->effect_handlers);
        emitter->effect_handlers = replacement;
        emitter->effect_handler_capacity = capacity;
    }
    emitter->effect_handlers[emitter->effect_handler_count].error_type = error_type;
    emitter->effect_handlers[emitter->effect_handler_count].label = label;
    emitter->effect_handlers[emitter->effect_handler_count].finally_count = finally_count;
    emitter->effect_handlers[emitter->effect_handler_count].group = group;
    emitter->effect_handlers[emitter->effect_handler_count].used = false;
    emitter->effect_handler_count += 1U;
    return true;
}

