static bool r_c17_push_finally(RC17Emitter *emitter, RHirNodeId node) {
    RC17Finally *replacement;
    size_t capacity;

    if (emitter->finally_count == emitter->finally_capacity) {
        capacity = emitter->finally_capacity == 0U ? 8U : emitter->finally_capacity * 2U;
        if ((capacity < emitter->finally_capacity) ||
            (capacity > (SIZE_MAX / sizeof(*replacement)))) {
            return r_c17_fail(emitter, R_FRONTEND_LIMIT_EXCEEDED);
        }
        replacement = r_c17_allocate(emitter, capacity * sizeof(*replacement));
        if (replacement == NULL) {
            return false;
        }
        if (emitter->finally_count != 0U) {
            (void)memcpy(
                replacement, emitter->finalies, emitter->finally_count * sizeof(*replacement));
        }
        r_c17_free(emitter, emitter->finalies);
        emitter->finalies = replacement;
        emitter->finally_capacity = capacity;
    }
    if (emitter->next_finally_label == UINT32_MAX) {
        return r_c17_fail(emitter, R_FRONTEND_LIMIT_EXCEEDED);
    }
    emitter->next_finally_label += UINT32_C(1);
    emitter->finalies[emitter->finally_count].node = node;
    emitter->finalies[emitter->finally_count].label = emitter->next_finally_label;
    emitter->finalies[emitter->finally_count].routes = NULL;
    emitter->finalies[emitter->finally_count].route_count = 0U;
    emitter->finalies[emitter->finally_count].route_capacity = 0U;
    emitter->finally_count += 1U;
    return true;
}

static bool r_c17_add_finally_payload_type(RC17Emitter *emitter, RTypeId type_id) {
    RTypeId *replacement;
    RTypeId value_type;
    size_t capacity;
    size_t index;

    value_type = r_c17_value_type(emitter, type_id);
    if (value_type == R_TYPE_ID_INVALID) {
        return r_c17_fail(emitter, R_FRONTEND_INTERNAL_ERROR);
    }
    for (index = 0U; index < emitter->finally_payload_type_count; ++index) {
        if (emitter->finally_payload_types[index] == value_type) {
            return true;
        }
    }
    if (emitter->finally_payload_type_count == emitter->finally_payload_type_capacity) {
        capacity = emitter->finally_payload_type_capacity == 0U
                       ? 8U
                       : emitter->finally_payload_type_capacity * 2U;
        if ((capacity < emitter->finally_payload_type_capacity) ||
            (capacity > (SIZE_MAX / sizeof(*replacement)))) {
            return r_c17_fail(emitter, R_FRONTEND_LIMIT_EXCEEDED);
        }
        replacement = r_c17_allocate(emitter, capacity * sizeof(*replacement));
        if (replacement == NULL) {
            return false;
        }
        if (emitter->finally_payload_type_count != 0U) {
            (void)memcpy(replacement,
                         emitter->finally_payload_types,
                         emitter->finally_payload_type_count * sizeof(*replacement));
        }
        r_c17_free(emitter, emitter->finally_payload_types);
        emitter->finally_payload_types = replacement;
        emitter->finally_payload_type_capacity = capacity;
    }
    emitter->finally_payload_types[emitter->finally_payload_type_count] = value_type;
    emitter->finally_payload_type_count += 1U;
    return true;
}

