/* Selects the handler for error_type: the innermost try statement with a clause for the error or
 * an ancestor, by the clause of the nearest ancestor (R-ERR-0003). It records that the catch label
 * is targeted, so a catch clause no transfer reaches is not emitted (its label would be unused C).
 */
static const RC17EffectHandler *r_c17_find_effect_handler(const RC17Emitter *emitter,
                                                          RTypeId error_type) {
    size_t end = emitter->effect_handler_count;

    while (end != 0U) {
        const size_t start = emitter->effect_handlers[end - 1U].group;
        RC17EffectHandler *nearest = NULL;
        uint32_t nearest_distance = UINT32_MAX;

        if (start >= end) {
            return NULL;
        }
        for (size_t index = start; index < end; ++index) {
            RC17EffectHandler *handler = &emitter->effect_handlers[index];
            const uint32_t distance =
                r_semantic_error_catch_distance(emitter->frontend, handler->error_type, error_type);

            if (distance < nearest_distance) {
                nearest = handler;
                nearest_distance = distance;
            }
        }
        if (nearest != NULL) {
            nearest->used = true;
            return nearest;
        }
        end = start;
    }
    return NULL;
}

static uint32_t r_c17_effect_tag(const RC17Emitter *emitter, RTypeId effects, RTypeId error_type) {
    const uint32_t count = r_semantic_effect_count(emitter->frontend, effects);
    uint32_t index;

    for (index = UINT32_C(0); index < count; ++index) {
        if (r_semantic_effect_at(emitter->frontend, effects, index) == error_type) {
            return index + UINT32_C(1);
        }
    }
    return UINT32_C(0);
}

