static bool r_c17_preflight_async_as_error(RC17Emitter *emitter,
                                           const RMirFunction *mir,
                                           const RMirInstruction *instruction) {
    const bool is_fs = instruction->standard_operation == R_STANDARD_CALL_FS_AS_ERROR;
    const RMirValueId source = r_c17_mir_operand(emitter, instruction, UINT32_C(0));
    const RMirInstruction *source_definition = r_c17_mir_value_definition(emitter, mir, source);

    if ((!is_fs && (instruction->standard_operation != R_STANDARD_CALL_IO_AS_ERROR)) ||
        (instruction->operand_count != UINT32_C(1)) ||
        !r_c17_call_borrow_mask_equals(&instruction->call_borrow_mask, UINT64_C(0), UINT64_C(0)) ||
        (instruction->result == R_MIR_VALUE_ID_INVALID) || (source_definition == NULL) ||
        (instruction->integer_value != UINT64_C(0)) ||
        (is_fs ? !r_c17_type_is_std_fs_error(emitter, instruction->auxiliary_type)
               : !r_c17_type_is_std_io_error(emitter, instruction->auxiliary_type)) ||
        !r_c17_type_is_std_error(emitter, instruction->type) ||
        (source_definition->type != instruction->auxiliary_type) ||
        r_c17_type_requires_drop(emitter, source_definition->type) ||
        r_c17_type_requires_drop(emitter, instruction->type) ||
        !r_c17_preflight_type_dependency(emitter, instruction->auxiliary_type, UINT32_C(0)) ||
        !r_c17_preflight_type_dependency(emitter, instruction->type, UINT32_C(0))) {
        return r_c17_fail(emitter, R_FRONTEND_NOT_LOWERABLE);
    }
    if (is_fs) {
        emitter->uses_std_fs = true;
    } else {
        emitter->uses_std_io = true;
    }
    return true;
}

