static bool r_c17_emit_async_call_initialize_name(RC17Emitter *emitter,
                                                  RSymbolId function_id,
                                                  RMirValueId result) {
    if (result == R_MIR_VALUE_ID_INVALID) {
        return r_c17_fail(emitter, R_FRONTEND_INTERNAL_ERROR);
    }
    return r_c17_format(emitter,
                        "r_async_call_initialize_%08" PRIu32 "_%08" PRIu32,
                        emitter->function_ordinals[function_id],
                        result - UINT32_C(1)) &&
           (!emitter->dyn_start_member ||
            r_c17_format(emitter, "_m%" PRIu32, emitter->dyn_start_tag));
}

