static bool r_c17_emit_async_fs_path_call(RC17Emitter *emitter,
                                          const RMirFunction *mir,
                                          const RSemanticSymbol *function,
                                          const RMirInstruction *instruction,
                                          uint32_t depth) {
    const bool from_str = instruction->standard_operation == R_STANDARD_CALL_FS_PATH_FROM_UTF8;
    const char *operation_name =
        from_str ? "r_std_fs_path_from_utf8" : "r_std_fs_path_from_utf8_bytes";
    const char *data_member = from_str ? ".data" : ".r_data";
    const char *length_member = from_str ? ".length" : ".r_len";
    const RMirValueId input = r_c17_mir_operand(emitter, instruction, UINT32_C(0));

    if (((instruction->standard_operation != R_STANDARD_CALL_FS_PATH_FROM_UTF8) &&
         (instruction->standard_operation != R_STANDARD_CALL_FS_PATH_FROM_UTF8_BYTES)) ||
        (input == R_MIR_VALUE_ID_INVALID) || (instruction->result == R_MIR_VALUE_ID_INVALID) ||
        !r_c17_indent(emitter, depth) ||
        !r_c17_format(
            emitter, "RStdStringView r_fs_path_input_%08" PRIu32 " = {\n", instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) || !r_c17_write(emitter, ".data = ") ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, input) ||
        !r_c17_format(emitter, "%s,\n", data_member) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) || !r_c17_write(emitter, ".length = ") ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, input) ||
        !r_c17_format(emitter, "%s,\n", length_member) || !r_c17_indent(emitter, depth) ||
        !r_c17_write(emitter, "};\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_format(
            emitter, "RStdFsPathResult r_fs_path_result_%08" PRIu32 " =\n", instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_format(emitter,
                      "%s(r_runtime_hosted_allocator(), r_fs_path_input_%08" PRIu32 ");\n",
                      operation_name,
                      instruction->result) ||
        !r_c17_indent(emitter, depth) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, " = (") || !r_c17_emit_value_type(emitter, instruction->type) ||
        !r_c17_write(emitter, "){0};\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_format(emitter,
                      "if (r_fs_path_result_%08" PRIu32 ".status == R_STD_FS_CALL_SUCCESS) {\n",
                      instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_payload.r_ok = ") ||
        !r_c17_format(emitter, "r_fs_path_result_%08" PRIu32 ".value;\n", instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_tag = UINT32_C(0);\n") ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_format(emitter,
                      "r_fs_path_result_%08" PRIu32 ".value = (RStdFsPath){0};\n",
                      instruction->result) ||
        !r_c17_indent(emitter, depth) || !r_c17_write(emitter, "} else {\n") ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_payload.r_error_00000001 = ") ||
        !r_c17_format(emitter, "r_fs_path_result_%08" PRIu32 ".error;\n", instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_tag = UINT32_C(1);\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_write(emitter, "}\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_emit_async_init_reference(emitter, "frame", false, instruction->result) ||
        !r_c17_write(emitter, " = 1;\n")) {
        return false;
    }
    return true;
}

static bool r_c17_emit_async_fs_owned_path_call(RC17Emitter *emitter,
                                                const RMirFunction *mir,
                                                const RSemanticSymbol *function,
                                                const RMirInstruction *instruction,
                                                uint32_t depth) {
    const bool is_clone = instruction->standard_operation == R_STANDARD_CALL_FS_PATH_CLONE;
    const bool is_join = instruction->standard_operation == R_STANDARD_CALL_FS_PATH_JOIN;
    const uint32_t expected_count = is_join ? UINT32_C(2) : UINT32_C(1);
    const char *operation_name = is_clone
                                     ? "r_std_fs_path_clone"
                                     : (is_join ? "r_std_fs_path_join" : "r_std_fs_path_to_utf8");
    const char *native_result_type =
        is_clone ? "RStdFsPathAllocResult" : (is_join ? "RStdFsPathResult" : "RStdFsStringResult");
    uint32_t operand_index;

    if ((!is_clone && !is_join &&
         (instruction->standard_operation != R_STANDARD_CALL_FS_PATH_TO_UTF8)) ||
        (instruction->operand_count != expected_count) ||
        (instruction->result == R_MIR_VALUE_ID_INVALID) || !r_c17_indent(emitter, depth) ||
        !r_c17_format(emitter,
                      "%s r_fs_owned_path_result_%08" PRIu32 " =\n",
                      native_result_type,
                      instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_format(emitter, "%s(", operation_name)) {
        return false;
    }
    for (operand_index = UINT32_C(0); operand_index < expected_count; ++operand_index) {
        const RMirValueId operand = r_c17_mir_operand(emitter, instruction, operand_index);

        if ((operand == R_MIR_VALUE_ID_INVALID) ||
            (operand_index != UINT32_C(0) && !r_c17_write(emitter, ", ")) ||
            !r_c17_emit_async_storage_reference(emitter, mir, function, false, operand)) {
            return false;
        }
    }
    if (!r_c17_write(emitter, ");\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, " = (") || !r_c17_emit_value_type(emitter, instruction->type) ||
        !r_c17_write(emitter, "){0};\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_format(emitter,
                      "if (r_fs_owned_path_result_%08" PRIu32
                      ".status == R_STD_FS_CALL_SUCCESS) {\n",
                      instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_payload.r_ok = ") ||
        !r_c17_format(
            emitter, "r_fs_owned_path_result_%08" PRIu32 ".value;\n", instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_tag = UINT32_C(0);\n") ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_format(
            emitter, "r_fs_owned_path_result_%08" PRIu32 ".value = (", instruction->result) ||
        !r_c17_emit_value_type(emitter, instruction->auxiliary_type) ||
        !r_c17_write(emitter, "){0};\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_write(emitter, "} else {\n") || !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_payload.r_error_00000001 =\n") ||
        !r_c17_indent(emitter, depth + UINT32_C(2)) ||
        !r_c17_format(
            emitter, "r_fs_owned_path_result_%08" PRIu32 ".error;\n", instruction->result) ||
        !r_c17_indent(emitter, depth + UINT32_C(1)) ||
        !r_c17_emit_async_storage_reference(emitter, mir, function, false, instruction->result) ||
        !r_c17_write(emitter, ".r_tag = UINT32_C(1);\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_write(emitter, "}\n") || !r_c17_indent(emitter, depth) ||
        !r_c17_emit_async_init_reference(emitter, "frame", false, instruction->result) ||
        !r_c17_write(emitter, " = 1;\n")) {
        return false;
    }
    return true;
}

