        base_type =
            base == NULL ? NULL : r_c17_type(emitter, r_c17_value_type(emitter, base->type));
        if ((base == NULL) || (base_type == NULL) ||
            ((base_type->kind != R_SEMANTIC_TYPE_FIXED_ARRAY) &&
             (base_type->kind != R_SEMANTIC_TYPE_SLICE) &&
             (base_type->kind != R_SEMANTIC_TYPE_ARRAY)) ||
            (base_type->base != slice_type->base) || (base->symbol != node->symbol) ||
            ((base_type->kind == R_SEMANTIC_TYPE_FIXED_ARRAY) &&
             (node->integer_value != base_type->length)) ||
            (((base_type->kind == R_SEMANTIC_TYPE_SLICE) ||
              (base_type->kind == R_SEMANTIC_TYPE_ARRAY)) &&
             (node->integer_value != UINT64_MAX))) {
            return r_c17_fail(emitter, R_FRONTEND_INTERNAL_ERROR);
        }
        if (node->child_count == UINT32_C(1)) {
            return true;
        }
        if ((node->operation != R_TOKEN_DOT_DOT) ||
            !r_c17_preflight_expression(
                emitter, r_c17_child(emitter, node, 1U), function_symbol, depth + 1U) ||
            ((node->child_count == UINT32_C(3)) &&
             !r_c17_preflight_expression(
                 emitter, r_c17_child(emitter, node, 2U), function_symbol, depth + 1U))) {
            return false;
        }
        lower = r_c17_node(emitter, r_c17_child(emitter, node, 1U));
        upper = node->child_count == UINT32_C(3)
                    ? r_c17_node(emitter, r_c17_child(emitter, node, 2U))
                    : lower;
        return (lower != NULL) && (upper != NULL) &&
                       r_c17_type_is_index_integer(emitter, lower->type) &&
                       r_c17_type_is_index_integer(emitter, upper->type)
                   ? true
                   : r_c17_fail(emitter, R_FRONTEND_INTERNAL_ERROR);
